/**
 * evaluate-rank-promotions — nightly cron (00:00 IST / 18:30 UTC).
 *
 * Iterates every signed-up user. For each user, recomputes the rank
 * ceiling from Postgres data (workout_logs total, signup date,
 * deployments_complete from user_progress) and upserts any missing
 * rank_promotions rows + updates the denormalized
 * user_profile.current_rank_code if it lags.
 *
 * Idempotent — UNIQUE (user_id, rank_code) means re-runs are no-ops
 * unless the user's qualified ceiling actually changed.
 *
 * verify_jwt: false  (cron-only). Auth header sent for header-shape
 * consistency with sibling cron functions.
 */

import { serve } from "https://deno.land/std@0.224.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2.39.3";
import {
  EvalState,
  highestQualified,
  LADDER,
  ranksUpTo,
  completionRateOverWindow,
  buildUserProgressMap,
  buildRankPromotionsMap,
  buildCurrentRankMap,
} from "../_shared/rank_engine.ts";
import {
  formatPromotionCeremony,
  rankAddressFor,
  rankDisplayFor,
} from "../_shared/ceremony_text.ts";
import { isAuthorizedCronCall } from "../_shared/cron_auth.ts";
import { logCronStart, logCronEnd } from "../_shared/cron_telemetry.ts";
import { fetchAllByIds, fetchAllPages } from "../_shared/paged_fetch.ts";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type",
  "Access-Control-Allow-Methods": "POST, OPTIONS",
};

const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;

// OPT-E — chunk size for the batch pre-fetch .in("user_id", chunk) calls below.
// Matches the BATCH_SIZE=100 precedent in weekly-recalc/index.ts:267 for the
// identical query shape (unchunked .in() risks PostgREST querystring-length
// limits once the user base is large enough — see docs/plan-reviews for the
// crossover estimate; 7 users today makes this a forward-looking guard, not a
// live bug, but the codebase already has a proven pattern for it).
const BATCH_SIZE = 100;

/** Fetches `columns` for every id in `userIds` from `table`, chunked at
 *  BATCH_SIZE, and returns the concatenated rows. Stops and surfaces the
 *  error on the first failing chunk (partial rows from earlier chunks are
 *  discarded by the caller via the error check, matching the all-or-nothing
 *  semantics of the old single unchunked .in() call).
 *
 *  ⚠️ `scripts/check_schema_column_refs.dart` cannot see the 3 call sites
 *  below — its regex only matches a string LITERAL directly inside
 *  `.from('...')` (documented as `.from(<variable>)` = "NOT validated —
 *  partial coverage by design" in that gate's own header). `table` and
 *  `columns` here are parameters, so a future column rename on
 *  user_progress/rank_promotions/user_profile won't be caught by that gate
 *  for these 3 reads — it WILL fail loudly at runtime instead (42703 →
 *  caught by the error check below → whole-tick abort + failed cron log),
 *  not silently degrade, but it's an unflagged blind spot worth knowing
 *  about before trusting a green gate run after a schema change here. */
async function fetchInChunks(
  // deno-lint-ignore no-explicit-any
  supabase: any,
  table: string,
  columns: string,
  userIds: string[],
  orderBy: string,
): Promise<{ data: Array<Record<string, unknown>>; error: unknown }> {
  // OI-79 — this used to chunk `userIds` into BATCH_SIZE groups and issue one
  // bare .in() per chunk. Chunking bounds the REQUEST (URL length); it does
  // nothing about the RESPONSE, which PostgREST still caps at db-max-rows
  // (1000) with HTTP 200 and error===null. For a table holding N rows per user
  // a 100-id chunk returns 100xN rows, so `rank_promotions` (one row per rank
  // achieved) clips at ~10 ranks/user regardless of how small the chunk is —
  // and clipped rank history reads as "never promoted", re-firing a promotion
  // ceremony the user already had. `fetchAllByIds` pages WITHIN each chunk, so
  // both dimensions are bounded.
  //
  // The {data, error} return shape is kept deliberately: the three call sites
  // funnel into one `prefetchErr` check that aborts the whole tick, and that
  // Unit C (§2.24) contract is unchanged.
  try {
    const data = await fetchAllByIds<Record<string, unknown>>(
      (chunk) => supabase.from(table).select(columns).in("user_id", chunk),
      userIds,
      { orderBy, chunkSize: BATCH_SIZE, label: `evaluate-rank-promotions ${table}` },
    );
    return { data, error: null };
  } catch (err) {
    return { data: [], error: err };
  }
}

serve(async (req: Request) => {
  if (req.method === "OPTIONS") {
    return new Response("ok", { headers: corsHeaders });
  }

  // audit-2026-05-16 E.14.C — installed shared `isAuthorizedCronCall(req)`
  // gate (no prior inline check existed; cron caller relied on
  // `verify_jwt: false` alone). Survives Vault/env key rotation: verifies
  // JWT signature against SUPABASE_JWT_SECRET + role-claim ===
  // 'service_role'. CRON_SECRET opaque-token escape hatch preserved
  // inside the helper. Closes Test #16 P1-D drift class.
  if (!await isAuthorizedCronCall(req)) {
    console.warn(`[cron-auth-gate] unauthorized caller; status=401`);
    return new Response(
      JSON.stringify({ error: "Unauthorized" }),
      { status: 401, headers: { ...corsHeaders, "Content-Type": "application/json" } },
    );
  }

  const requestId = crypto.randomUUID().split("-")[0];
  const logId = await logCronStart("evaluate-rank-promotions");

  try {
    const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);

    // 1. Pull the user roster (id + signup time).
    //    OI-79: paged. This is the WHOLE roster with no filter, so it is the
    //    first read in this function to hit db-max-rows — at 1000 users every
    //    later signup would silently stop being evaluated for promotion.
    let users: Array<Record<string, unknown>> | null = null;
    let usersErr: unknown = null;
    try {
      users = await fetchAllPages<Record<string, unknown>>(
        () => supabase.from("users").select("id, created_at"),
        { orderBy: "id", label: "evaluate-rank-promotions roster" },
      );
    } catch (e) {
      usersErr = e;
    }

    if (usersErr || !users) {
      console.error(`[evaluate-rank-promotions] request_id=${requestId}`, usersErr);
      await logCronEnd(logId, "failed", {
        httpStatus: 500,
        requestId,
        errorSummary: String(usersErr),
      });
      return new Response(
        JSON.stringify({ error: "Internal server error", request_id: requestId }),
        { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } },
      );
    }

    // OPT-E — pre-fetch reads that were previously issued once PER USER
    // (user_progress, rank_promotions, user_profile.current_rank_code) in a
    // single .in() call each. Reduces N*3 queries/tick to 3. Read totalWorkouts
    // (COUNT below) and completionRateOverWindow (via rank_engine, called
    // conditionally per officer-track gate) stay per-user: COUNT batching needs
    // a GROUP BY RPC (invisible to check_schema_column_refs + a migration-
    // sequencing risk if the function deploys before the migration lands), and
    // completionRateOverWindow is rarely invoked (only for users 1+ year in who
    // already cleared every lower gate) with a per-rank window — not worth
    // batching. Batch-read-in-a-whole-batch-cron → throw (Unit C §2.24 precedent,
    // matches the users-roster-fetch abort above: a failed pre-fetch here is as
    // fatal as a failed roster fetch, not a per-user condition).
    const userIds = (users as Array<Record<string, unknown>>).map((u) => u.id as string);
    const [progressBatch, ranksBatch, profileBatch] = await Promise.all([
      fetchInChunks(
        supabase,
        "user_progress",
        "user_id, current_streak_days, deployments_complete, longest_gap_days, last_workout_date",
        userIds,
        "id",
      ),
      // rank_promotions is the multi-row-per-user one — see the note in
      // fetchInChunks for why chunking alone did not bound it.
      fetchInChunks(supabase, "rank_promotions", "user_id, rank_code", userIds, "id"),
      fetchInChunks(supabase, "user_profile", "user_id, current_rank_code", userIds, "id"),
    ]);
    const prefetchErr = progressBatch.error ?? ranksBatch.error ?? profileBatch.error;
    if (prefetchErr) {
      console.error(`[evaluate-rank-promotions] request_id=${requestId} pre-fetch batch err`, prefetchErr);
      await logCronEnd(logId, "failed", {
        httpStatus: 500,
        requestId,
        errorSummary: String(prefetchErr),
      });
      return new Response(
        JSON.stringify({ error: "Internal server error", request_id: requestId }),
        { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } },
      );
    }
    const progressMap = buildUserProgressMap(progressBatch.data ?? []);
    const ranksMap = buildRankPromotionsMap(ranksBatch.data ?? []);
    const currentRankMap = buildCurrentRankMap(profileBatch.data ?? []);

    let evaluated = 0;
    let promoted = 0;
    const now = new Date();

    for (const u of users as Array<Record<string, unknown>>) {
      const userId = u.id as string;
      const signupAt = new Date(u.created_at as string);
      const weeksSinceSignup = Math.floor(
        (now.getTime() - signupAt.getTime()) / (7 * 24 * 3600 * 1000),
      );

      // Total workouts done (cloud source of truth).
      // Unit C (§2.24) — per-user reads in this whole-batch cron CAPTURE the error
      // and SKIP just this user (console.error + continue, matching the insert-error
      // idiom at the upsert below). Pre-fix a silent failure coerced to `?? 0` / null
      // → a WRONG rank state (streak/workouts/deployments read as 0) → a generic or
      // mis-graded promotion ceremony. A top-level throw would zero the WHOLE day's
      // promotions, so skip-one-user (self-heals next daily run) is correct here.
      const { count: totalWorkouts, error: totalWErr } = await supabase
        .from("workout_logs")
        .select("*", { count: "exact", head: true })
        .eq("user_id", userId);
      if (totalWErr) {
        console.error(`[evaluate-rank-promotions] user=${userId} totalWorkouts err`, totalWErr);
        continue;
      }

      // OPT-E — progress row comes from the batch pre-fetch above (was a
      // per-user .maybeSingle() query; absent-from-map = no row for this user,
      // same as the old query's `data: null` — NOT an error, so `?? 0` below
      // still carries the same meaning it always did).
      const progressRow = progressMap.get(userId) ?? null;

      // Compute days since last workout for the maxGapDays gate (MCPO).
      let lastWorkoutDaysAgo: number | null = null;
      const lastWorkoutDate = progressRow?.last_workout_date as string | undefined;
      if (lastWorkoutDate) {
        const last = new Date(lastWorkoutDate as string);
        lastWorkoutDaysAgo = Math.floor(
          (now.getTime() - last.getTime()) / (24 * 3600 * 1000),
        );
      }

      const state: EvalState = {
        streak: (progressRow?.current_streak_days as number | undefined) ?? 0,
        totalWorkouts: totalWorkouts ?? 0,
        weeksSinceSignup,
        deploymentsComplete:
          (progressRow?.deployments_complete as number | undefined) ?? 0,
        lastWorkoutDaysAgo,
        completionRateProvider: (windowWeeks: number) =>
          completionRateOverWindow(supabase, userId, windowWeeks),
      };

      const winner = await highestQualified(state);
      const eligibleCodes = ranksUpTo(winner.code).map((r) => r.code);

      // OPT-E — what's already on file, from the batch pre-fetch above (was a
      // per-user .select().eq() query). Absent-from-map = no earned ranks yet
      // for this user, same as the old query's empty array.
      const existingCodes = ranksMap.get(userId) ?? new Set<string>();

      const toInsert = eligibleCodes
        .filter((c) => !existingCodes.has(c))
        .map((c) => ({
          user_id: userId,
          rank_code: c,
          trigger_type: "combined",
          trigger_metadata: {
            streak: state.streak,
            total_workouts: state.totalWorkouts,
            weeks: state.weeksSinceSignup,
            source: "cron",
          },
        }));

      if (toInsert.length > 0) {
        const { error: insertErr } = await supabase
          .from("rank_promotions")
          .upsert(toInsert, { onConflict: "user_id,rank_code" });
        if (insertErr) {
          console.error(
            `[evaluate-rank-promotions] user=${userId} insert err`,
            insertErr,
          );
          continue;
        }
        promoted += toInsert.length;

        // Insert a Captain-voice ceremony row in ai_coach_interactions for
        // each newly-earned rank, in ladder order. The client surfaces these
        // via _restoreCoachInteractions → coachBox → ChatHistoryNotifier.
        //
        // We reconstruct "old rank" as the highest code already on file
        // before this batch (existingCodes), falling back to "SD2" for a
        // brand-new user. Then we walk the toInsert list in ladder order.
        const ladderOrder = LADDER.map((r) => r.code);
        const sortedNew = toInsert
          .map((row) => row.rank_code)
          .sort(
            (a, b) => ladderOrder.indexOf(a) - ladderOrder.indexOf(b),
          );

        // Determine the starting "previous" rank for ceremony sequencing.
        let prevCode: string = existingCodes.size > 0
          ? [...existingCodes].sort(
              (a, b) => ladderOrder.indexOf(a) - ladderOrder.indexOf(b),
            ).at(-1)! // highest existing rank before this batch
          : "SD2";

        for (const newCode of sortedNew) {
          const ceremonyText = formatPromotionCeremony({
            oldRankAddress: rankAddressFor(prevCode),
            oldRankCode: prevCode,
            newRankCode: newCode,
            newRankDisplay: rankDisplayFor(newCode),
            newRankAddress: rankAddressFor(newCode),
            totalWorkouts: state.totalWorkouts,
            weeksHeld: state.weeksSinceSignup,
          });

          const { error: ceremonyErr } = await supabase
            .from("ai_coach_interactions")
            .insert({
              user_id: userId,
              channel: "promotion_ceremony",
              user_message: "",
              ai_response: ceremonyText,
              model_used: "ceremony_template",
              created_at: new Date().toISOString(),
            });

          if (ceremonyErr) {
            // Non-fatal — log but keep going. The rank_promotion row is
            // already committed; a missing ceremony message is recoverable.
            console.warn(
              `[evaluate-rank-promotions] user=${userId} ceremony insert err for ${newCode}`,
              ceremonyErr,
            );
          }

          prevCode = newCode;
        }
      }

      // Sync denormalized current rank — only ever PROMOTE, never demote.
      //
      // Diagnose 3a7b9f (2026-05-27): pre-fix the cron unconditionally
      // overwrote `current_rank_code` with `winner.code` (the currently-
      // qualifying ceiling). When a user broke a sailor-track streak gate
      // (e.g. SD1 → streakAtLeast: 7), `winner.code` recomputed to SD2 and
      // the user was silently demoted. Rank is permanent: `rank_promotions`
      // is the append-only event log; `user_profile.current_rank_code` is
      // its denormalization and must monotonically increase.
      // OPT-E — current_rank_code comes from the batch pre-fetch above (was a
      // per-user .maybeSingle() query). Absent-from-map = no profile row yet,
      // same as the old query's `data: null`.
      const currentCode = currentRankMap.get(userId) ?? null;
      const currentOrdinal = currentCode === null
        ? -1
        : (LADDER.find((r) => r.code === currentCode)?.ordinal ?? -1);
      if (winner.ordinal > currentOrdinal) {
        await supabase.from("user_profile").update({
          current_rank_code: winner.code,
          current_rank_achieved_at: now.toISOString(),
        }).eq("user_id", userId);
      }

      evaluated += 1;
    }

    await logCronEnd(logId, "success", { httpStatus: 200, requestId });
    return new Response(
      JSON.stringify({
        status: "success",
        evaluated,
        promoted,
        request_id: requestId,
      }),
      { status: 200, headers: { ...corsHeaders, "Content-Type": "application/json" } },
    );
  } catch (err) {
    console.error(`[evaluate-rank-promotions] request_id=${requestId}`, err);
    await logCronEnd(logId, "failed", {
      httpStatus: 500,
      requestId,
      errorSummary: String(err),
    });
    return new Response(
      JSON.stringify({ error: "Internal server error", request_id: requestId }),
      { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } },
    );
  }
});

// Mirror of `lib/core/services/rank_ladder_data.dart`. Update both
// files in lockstep when migration 039/045 ladder rows change.
//
// APK Test #6 Plan G (G-8): adds Lt at ordinal 7, rebalances sailor
// gates, switches officer track to completionRateMinimum primary,
// MCPO becomes the transition rank with completion rate + maxGapDays.

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2.39.3";

export interface RankLadderEntry {
  code: string;
  displayName: string;
  shortName: string;
  ordinal: number;
  minWeeks: number;
  category: 'sailor' | 'officer';
  isTerminal: boolean;
}

export interface RankGate {
  streakAtLeast?: number;
  totalWorkoutsAtLeast?: number;
  deploymentsCompleteAtLeast?: number;
  minWeeksSinceSignup?: number;
  maxGapDays?: number;
  completionRateMinimum?: number;
  completionRateWindowWeeks?: number;
}

// 11-rung ladder, ordinal 0..10. Mirrors lib/core/services/rank_ladder_data.dart.
export const kRankLadder: RankLadderEntry[] = [
  { code: 'SD2',   displayName: 'Seaman 2nd Class',          shortName: 'SEAMAN 2',       ordinal: 0,  minWeeks: 0,   category: 'sailor',  isTerminal: false },
  { code: 'SD1',   displayName: 'Seaman 1st Class',          shortName: 'SEAMAN 1',       ordinal: 1,  minWeeks: 1,   category: 'sailor',  isTerminal: false },
  { code: 'LS',    displayName: 'Leading Seaman',            shortName: 'LEADING SEAMAN', ordinal: 2,  minWeeks: 4,   category: 'sailor',  isTerminal: false },
  { code: 'PO',    displayName: 'Petty Officer',             shortName: 'PETTY OFFICER',  ordinal: 3,  minWeeks: 12,  category: 'sailor',  isTerminal: false },
  { code: 'CPO',   displayName: 'Chief Petty Officer',       shortName: 'CHIEF PO',       ordinal: 4,  minWeeks: 26,  category: 'sailor',  isTerminal: false },
  { code: 'MCPO',  displayName: 'Master Chief Petty Officer',shortName: 'MASTER CHIEF',   ordinal: 5,  minWeeks: 52,  category: 'sailor',  isTerminal: false },
  { code: 'SubLt', displayName: 'Sub Lieutenant',            shortName: 'SUB LT',         ordinal: 6,  minWeeks: 104, category: 'officer', isTerminal: false },
  { code: 'Lt',    displayName: 'Lieutenant',                shortName: 'LIEUTENANT',     ordinal: 7,  minWeeks: 130, category: 'officer', isTerminal: false },
  { code: 'LtCdr', displayName: 'Lieutenant Commander',      shortName: 'LT CDR',         ordinal: 8,  minWeeks: 156, category: 'officer', isTerminal: false },
  { code: 'Cdr',   displayName: 'Commander',                 shortName: 'CDR',            ordinal: 9,  minWeeks: 208, category: 'officer', isTerminal: false },
  { code: 'Capt',  displayName: 'Captain',                   shortName: 'CAPTAIN',        ordinal: 10, minWeeks: 260, category: 'officer', isTerminal: true  },
];

export const kRankGates: Record<string, RankGate> = {
  'SD2':   {},
  'SD1':   { streakAtLeast: 7,  minWeeksSinceSignup: 1 },
  'LS':    { streakAtLeast: 14, minWeeksSinceSignup: 4 },
  'PO':    { streakAtLeast: 30, minWeeksSinceSignup: 12, deploymentsCompleteAtLeast: 2 },
  'CPO':   { streakAtLeast: 50, minWeeksSinceSignup: 26, deploymentsCompleteAtLeast: 3 },
  'MCPO':  { minWeeksSinceSignup: 52,  completionRateMinimum: 0.80, completionRateWindowWeeks: 12,  maxGapDays: 14 },
  'SubLt': { minWeeksSinceSignup: 104, completionRateMinimum: 0.80, completionRateWindowWeeks: 26  },
  'Lt':    { minWeeksSinceSignup: 130, completionRateMinimum: 0.80, completionRateWindowWeeks: 26  },
  'LtCdr': { minWeeksSinceSignup: 156, completionRateMinimum: 0.80, completionRateWindowWeeks: 52  },
  'Cdr':   { minWeeksSinceSignup: 208, completionRateMinimum: 0.80, completionRateWindowWeeks: 52  },
  'Capt':  { minWeeksSinceSignup: 260, completionRateMinimum: 0.85, completionRateWindowWeeks: 104 },
};

// Legacy aliases retained so existing callers (highestQualified / ranksUpTo /
// callers that imported `LADDER` / `GATES`) keep compiling without churn.
export const LADDER = kRankLadder;
export const GATES = kRankGates;

export interface EvalState {
  streak: number;
  totalWorkouts: number;
  weeksSinceSignup: number;
  deploymentsComplete: number;
  lastWorkoutDaysAgo: number | null;
  completionRateProvider: (windowWeeks: number) => Promise<number> | number;
}

export async function qualifies(code: string, s: EvalState): Promise<boolean> {
  const gate = kRankGates[code];
  if (!gate) return false;
  const entry = kRankLadder.find((r) => r.code === code);
  if (!entry) return false;
  // Ladder-level minWeeks gate (always required).
  if (s.weeksSinceSignup < entry.minWeeks) return false;
  if (gate.streakAtLeast !== undefined && s.streak < gate.streakAtLeast) return false;
  if (gate.totalWorkoutsAtLeast !== undefined && s.totalWorkouts < gate.totalWorkoutsAtLeast) return false;
  if (gate.deploymentsCompleteAtLeast !== undefined && s.deploymentsComplete < gate.deploymentsCompleteAtLeast) return false;
  if (gate.minWeeksSinceSignup !== undefined && s.weeksSinceSignup < gate.minWeeksSinceSignup) return false;
  if (gate.maxGapDays !== undefined && s.lastWorkoutDaysAgo !== null && s.lastWorkoutDaysAgo > gate.maxGapDays) return false;
  if (gate.completionRateMinimum !== undefined) {
    const window = gate.completionRateWindowWeeks ?? 26;
    const rate = await Promise.resolve(s.completionRateProvider(window));
    if (rate < gate.completionRateMinimum) return false;
  }
  return true;
}

// Highest rung EARNED, evaluated SEQUENTIALLY — no skipping. Mirror of the
// client `RankService._qualifiedRankCode` (2026-05-31, diagnose b9f4d2, ADR
// rank-sequential). Walk from the bottom; advance only while each successive
// rung's gate passes; STOP at the first failure. The deployment-gated PO/CPO
// rungs cannot be leap-frogged by an officer-track completion-rate qualifier.
// (Pre-fix this picked the highest INDEPENDENTLY-qualifying rung.)
export async function highestQualified(s: EvalState): Promise<RankLadderEntry> {
  let winner = kRankLadder[0]; // SD2 — ordinal 0, empty gate
  for (let i = 1; i < kRankLadder.length; i++) {
    const r = kRankLadder[i];
    if (await qualifies(r.code, s)) {
      winner = r;
    } else {
      break; // sequential: a failed gate blocks every rung above it
    }
  }
  return winner;
}

export function ranksUpTo(code: string): RankLadderEntry[] {
  const target = kRankLadder.find((r) => r.code === code);
  if (!target) return [kRankLadder[0]];
  return kRankLadder.filter((r) => r.ordinal <= target.ordinal);
}

/// SQL-backed completion-rate computation used by the cron caller —
/// scans `scheduled_workouts` rows for the user / window. Rest days
/// and pre-onboarding rows are excluded from both numerator and
/// denominator so the rate matches the client's
/// `WorkoutRepository.completionRateOverWindow` semantics.
export async function completionRateOverWindow(
  supabase: SupabaseClient,
  userId: string,
  windowWeeks: number,
): Promise<number> {
  if (windowWeeks <= 0) return 0.0;
  const sinceIso = new Date(Date.now() - windowWeeks * 7 * 24 * 3600 * 1000)
    .toISOString();
  // ⚠ ADDING A RANK: a window > 142 weeks (≈1000 days) breaks the waiver
  // below. `completionRateOverWindow` would then sum a denominator clipped at
  // 1000, return an inflated completion rate, and promote a user who did not
  // qualify — silently, HTTP 200, with the gate still green because the waiver
  // suppresses it. Route this read through paged_fetch at that point.
  //
  // The numbers: largest window actually shipped is `'Capt':
  // completionRateWindowWeeks: 104` (RANK_GATES, :56) = 728 days, so worst
  // case is 728 rows against the 1000-row cap — real headroom 1.37x, NOT the
  // 2.7x an earlier version of this waiver implied by citing "max ~52" weeks /
  // "~365 rows". Corrected 2026-08-01 (round-1 review): the numbers were
  // wrong, the conclusion survives. The 1-row-per-user-per-day premise is
  // evidence, not assumption — live UNIQUE index
  // `uq_scheduled_workouts_user_date` on (user_id, scheduled_date), confirmed
  // via pg_index on dedsavbjuwgarrhphgnl.
  //
  // oi79-ok: per-user window read, bounded to 728 rows worst case (see above);
  // paging a read that cannot reach the cap would add a round-trip to the
  // hottest loop in the rank cron for no correctness gain.
  const { data, error } = await supabase
    .from('scheduled_workouts')
    .select('status, scheduled_date')
    .eq('user_id', userId)
    .gte('scheduled_date', sinceIso.split('T')[0]);
  if (error) {
    // Unit C (§2.24) — return a -1.0 SENTINEL (not 0.0) on a transient query error.
    // The only consumer is the gate `if (rate < gate.completionRateMinimum) return
    // false` (qualifies, :88): -1.0 < any minimum → the completion-rate gate FAILS →
    // `highestQualified` breaks at this rung and KEEPS every lower rank the user
    // already earned. Pre-fix `return 0.0` did the same for THIS gate, but 0.0 is a
    // legitimate value that a `>=` refactor / an averaging consumer would silently
    // mistake for "0% completion"; -1.0 is an unambiguous can't-compute marker and
    // keeps the return a `number`. NB: the `windowWeeks <= 0` guard above stays 0.0
    // (an invalid window is a caller bug, not a DB failure — do NOT unify them).
    console.error('[rank_engine] completionRate query failed', error);
    return -1.0;
  }
  let scheduled = 0;
  let completed = 0;
  for (const row of data ?? []) {
    if (row.status === 'rest') continue;
    // Cloud `scheduled_workouts` has NO `reason` column — it only ever existed
    // in the client's local Hive model. Pre-onboarding placeholder days are
    // written with status='rest' (workout_schedule_read_service.dart:303-309),
    // so the status check above ALREADY excludes them. Selecting `reason` here
    // 42703'd → completionRate silently returned 0.0 for everyone since
    // 2026-05-01. closes-diagnose: d7c3f1.
    scheduled++;
    if (row.status === 'completed') completed++;
  }
  return scheduled === 0 ? 0.0 : completed / scheduled;
}

// OPT-E — pure grouping helpers for evaluate-rank-promotions' batch pre-fetch
// (one .in("user_id", allIds) call per table instead of one query per user per
// cron tick). Kept here rather than in index.ts so they're importable in a Deno
// test without triggering index.ts's module-level `serve()` (which binds a port
// on import). Each takes the raw rows from a `.in()` select and groups them by
// user_id — the actual `.in()` fetch + its error handling stays in index.ts
// (batch-read-in-a-whole-batch-cron → throw, per Unit C §2.24 precedent).

/** user_progress rows keyed by user_id. UNIQUE(user_id) at the DB level
 *  (migration 001) guarantees at most one row per key — no last-write-wins risk. */
export function buildUserProgressMap(
  rows: Array<Record<string, unknown>>,
): Map<string, Record<string, unknown>> {
  const map = new Map<string, Record<string, unknown>>();
  for (const row of rows) {
    map.set(row.user_id as string, row);
  }
  return map;
}

/** Already-earned rank codes per user, from rank_promotions (one row per
 *  earned (user_id, rank_code) pair — UNIQUE(user_id, rank_code), migration 039). */
export function buildRankPromotionsMap(
  rows: Array<Record<string, unknown>>,
): Map<string, Set<string>> {
  const map = new Map<string, Set<string>>();
  for (const row of rows) {
    const uid = row.user_id as string;
    if (!map.has(uid)) map.set(uid, new Set());
    map.get(uid)!.add(row.rank_code as string);
  }
  return map;
}

/** user_profile.current_rank_code per user. UNIQUE(user_id) (migration 001)
 *  guarantees at most one row per key. */
export function buildCurrentRankMap(
  rows: Array<Record<string, unknown>>,
): Map<string, string | null> {
  const map = new Map<string, string | null>();
  for (const row of rows) {
    map.set(row.user_id as string, (row.current_rank_code as string | null) ?? null);
  }
  return map;
}

// Promotion ceremony text formatter — single source for the Captain's
// voice on rank advances. Used by evaluate-rank-promotions Edge Function.
//
// Source: Captain Manual §4 + APK Test #4 Plan C / C2.
//
// NOTE: rank codes match rank_engine.ts (SD2, SD1, LS, PO, CPO, MCPO,
// SubLt, LtCdr, Cdr, Capt). Update both files in lockstep.

export interface CeremonyInput {
  oldRankAddress: string; // e.g., "Recruit", "Sailor", "Petty Officer"
  oldRankCode: string;    // e.g., "SD2", "PO"
  newRankCode: string;    // e.g., "SD1", "SubLt"
  newRankDisplay: string; // e.g., "Seaman 1st Class", "Sub Lieutenant"
  newRankAddress: string; // e.g., "Sailor", "Lieutenant"
  totalWorkouts: number;
  weeksHeld: number;
}

const RANK_ADDRESS: Record<string, string> = {
  SD2:   "Recruit",
  SD1:   "Sailor",
  LS:    "Sailor",
  PO:    "Petty Officer",
  CPO:   "Chief",
  MCPO:  "Master Chief",
  SubLt: "Lieutenant",
  LtCdr: "Lieutenant Commander",
  Cdr:   "Commander",
  Capt:  "Captain",
};

const RANK_DISPLAY: Record<string, string> = {
  SD2:   "Seaman 2nd Class",
  SD1:   "Seaman 1st Class",
  LS:    "Leading Seaman",
  PO:    "Petty Officer",
  CPO:   "Chief Petty Officer",
  MCPO:  "Master Chief Petty Officer",
  SubLt: "Sub Lieutenant",
  LtCdr: "Lieutenant Commander",
  Cdr:   "Commander",
  Capt:  "Captain",
};

export function rankAddressFor(code: string): string {
  return RANK_ADDRESS[code] ?? "Sailor";
}

export function rankDisplayFor(code: string): string {
  return RANK_DISPLAY[code] ?? code;
}

export function formatPromotionCeremony(input: CeremonyInput): string {
  const {
    oldRankAddress,
    oldRankCode,
    newRankCode,
    newRankDisplay,
    newRankAddress,
    totalWorkouts,
    weeksHeld,
  } = input;

  // Officer-track entry: Sub Lieutenant promotion from any enlisted rank.
  // The gate is 2 years of service + 80% completion (rolling 26 weeks) — NOT a
  // workout count. totalWorkouts is stated as a stat of the journey, never as
  // the threshold (the false "104 workouts" claim was OBS-1 / diagnose f1a9d3).
  const officerCrossing =
    newRankCode === "SubLt" &&
    (oldRankCode === "PO" ||
      oldRankCode === "CPO" ||
      oldRankCode === "MCPO" ||
      oldRankCode === "SD1" ||
      oldRankCode === "LS" ||
      oldRankCode === "SD2");

  if (officerCrossing) {
    return (
      `${oldRankAddress}, ${weeksHeld} weeks on the line, ${totalWorkouts} ` +
      `sessions logged straight. You've crossed onto the officer track. ` +
      `Promotion: ${newRankDisplay}. Carry on.`
    );
  }

  // Lt Cdr — the Contract milestone. The gate is 3 years of service + 80%
  // completion (rolling 52 weeks), NOT a session count (OBS-1 / diagnose f1a9d3).
  if (newRankCode === "LtCdr") {
    return (
      `${oldRankAddress}, ${weeksHeld} weeks on the line, ${totalWorkouts} ` +
      `sessions logged honest. The contract is met. ` +
      `Promotion: ${newRankDisplay}. Address change: ${newRankAddress}. Carry on.`
    );
  }

  // Standard format for all other promotions.
  return (
    `${oldRankAddress}, you've completed ${totalWorkouts} sessions and ` +
    `held the line ${weeksHeld} weeks. ` +
    `Promotion: ${newRankDisplay}. ` +
    `Address change: ${newRankAddress}. Carry on.`
  );
}

/**
 * cron_auth.ts — shared-secret auth gate for cron-dispatched Edge Functions.
 *
 * Rewritten 2026-07-26 (closes-diagnose: c3f8a1). See HISTORY at the bottom —
 * the two previous designs both failed in production, and the second failed
 * silently for roughly eight weeks.
 *
 * AUTH MODEL
 * ----------
 * A single opaque shared secret. The caller must present
 * `Authorization: Bearer <CRON_SECRET>`, where `CRON_SECRET` is an Edge
 * Function secret whose value also lives in the Vault row `cron_secret`, read
 * by `private.cron_get_secret()` and interpolated into every `cron.job`
 * command (migrations 107/108).
 *
 * WHY A SHARED SECRET RATHER THAN A JWT
 * -------------------------------------
 * This is machine-to-machine auth between pg_cron and the Edge runtime. There
 * is no user identity to carry, no claims to inspect and no delegation — a
 * signed token buys nothing here, and every JWT-shaped attempt has coupled the
 * gate to platform key management that then changed underneath it:
 *
 *   - Attempt 1 compared the token to `SUPABASE_SERVICE_ROLE_KEY`. Broke when
 *     the Vault copy and the env copy drifted (diagnose 5a65bd).
 *   - Attempt 2 verified the signature against `SUPABASE_JWT_SECRET` — a
 *     variable Supabase does not inject and **forbids creating**, because the
 *     platform reserves the `SUPABASE_` prefix for secret names. Unsatisfiable
 *     by construction; every cron call 401'd from the day it deployed.
 *
 * A string comparison has no such coupling. It is unaffected by the JWT
 * signing-key migration now underway on this project and by the deprecation of
 * `SUPABASE_ANON_KEY` / `SUPABASE_SERVICE_ROLE_KEY`.
 *
 * ⚠ THE SECRET IS THE ONLY GATE. Cron functions run `verify_jwt=false`, so
 * their URLs accept unauthenticated POSTs from anywhere and this comparison is
 * all that stands between the open internet and a privileged fan-out (push
 * sends, Gemini spend, storage deletion). `CRON_SECRET` must be long and
 * cryptographically random — `openssl rand -hex 32`. Never a memorable phrase.
 *
 * USAGE (per cron function)
 * -------------------------
 *   import { isAuthorizedCronCall } from "../_shared/cron_auth.ts";
 *
 *   Deno.serve(async (req) => {
 *     if (req.method === "OPTIONS") return new Response("ok", { headers: corsHeaders });
 *     if (!await isAuthorizedCronCall(req)) {
 *       return new Response(JSON.stringify({ error: "Unauthorized" }), {
 *         status: 401, headers: { ...corsHeaders, "Content-Type": "application/json" },
 *       });
 *     }
 *     const logId = await logCronStart("<slug>");   // AFTER the gate — see below
 *     // ... handler body
 *   });
 *
 * ⚠ KEEP `logCronStart` AFTER THIS GATE. It is tempting to move it earlier so
 * that rejected calls leave a telemetry row — the 2026-07-26 batch considered
 * exactly that. Don't: on a `verify_jwt=false` endpoint it would hand every
 * anonymous caller an unauthenticated INSERT into `public.cron_call_log`.
 * Outage visibility is provided instead by `alert_cron_silence` (migration
 * 109), which alerts on the ABSENCE of successful runs and therefore needs no
 * writes from unauthenticated callers.
 */

/**
 * Constant-time string comparison.
 *
 * Both sides are hashed to a fixed 32-byte digest first, then compared with an
 * XOR-accumulate that always walks the full length. This leaks neither the
 * secret's length nor the position of the first differing byte, whereas a plain
 * `!==` short-circuits on the first mismatch and is measurable over enough
 * requests.
 *
 * Worth the few microseconds here specifically because this comparison is the
 * ONLY gate on 16 publicly-reachable endpoints (see the warning above), and the
 * secret in production is currently low-entropy by explicit accepted risk
 * (migration 107 header) — a weak secret plus a timing oracle is materially
 * worse than either alone.
 */
async function timingSafeEqual(a: string, b: string): Promise<boolean> {
  const enc = new TextEncoder();
  const [da, db] = await Promise.all([
    crypto.subtle.digest("SHA-256", enc.encode(a)),
    crypto.subtle.digest("SHA-256", enc.encode(b)),
  ]);
  const va = new Uint8Array(da);
  const vb = new Uint8Array(db);
  let diff = 0;
  for (let i = 0; i < va.length; i++) diff |= va[i] ^ vb[i];
  return diff === 0;
}

/**
 * True when the request carries `Authorization: Bearer <CRON_SECRET>`.
 *
 * False on a missing header, a malformed bearer, an unset `CRON_SECRET`, or any
 * mismatch. Never throws — safe to call without try/catch.
 */
export async function isAuthorizedCronCall(req: Request): Promise<boolean> {
  try {
    const authHeader = req.headers.get("Authorization") ?? "";
    if (!authHeader.startsWith("Bearer ")) {
      console.warn("[cron_auth] missing or malformed Authorization header");
      return false;
    }
    const token = authHeader.slice("Bearer ".length).trim();
    if (token.length === 0) {
      console.warn("[cron_auth] empty bearer token");
      return false;
    }

    // Trimmed on BOTH sides. A trailing newline pasted into the dashboard
    // secret would otherwise reject every call with no visible reason.
    const cronSecret = (Deno.env.get("CRON_SECRET") ?? "").trim();
    if (cronSecret.length === 0) {
      console.warn(
        "[cron_auth] CRON_SECRET is unset — every cron call will be rejected. " +
          "Set it in Project Settings -> Edge Functions -> Secrets, matching " +
          "the `cron_secret` Vault row exactly.",
      );
      return false;
    }

    if (!await timingSafeEqual(token, cronSecret)) {
      console.warn("[cron_auth] bearer token does not match CRON_SECRET");
      return false;
    }

    return true;
  } catch (err) {
    // Defensive — never let the auth gate crash its caller.
    console.error("[cron_auth] unexpected error:", err);
    return false;
  }
}

/*
 * HISTORY
 * -------
 * 2026-05-11 (7ad0c4)  Gate introduced; 8 cron functions were publicly callable.
 * 2026-05-12 (audit P0) Vault `service_role_key` row was empty, so the header
 *                       went out as `Bearer null` → 401 on every tick, 12 jobs.
 * 2026-05-15 (5a65bd)  Env-equality check broke on Vault/env key drift. That
 *                       write-up proposed "replace the brittle env-equality
 *                       check with a JWT signature+role decode" as the
 *                       permanent class fix.
 * 2026-05-16           The class fix shipped. It depended on
 *                       `SUPABASE_JWT_SECRET`, which cannot exist. The fix
 *                       made the bug permanent instead of ending it.
 * 2026-07-26 (c3f8a1)  Discovered: ~8 weeks of total cron silence. Three
 *                       safeguards had failed together — telemetry sat behind
 *                       the failing gate, pg_cron reports `succeeded` for any
 *                       dispatch regardless of HTTP status, and the health
 *                       alert computed a rate from the table the failure kept
 *                       empty. Replaced with this shared-secret gate; the
 *                       `deno.land/x/jose` dependency is gone with it, closing
 *                       a remote-dep-rot risk this repo has already been bitten
 *                       by (feedback_mistake_remote_dep_rot).
 */

/**
 * cron_telemetry — per-invocation execution telemetry for cron Edge Functions.
 *
 * Closes audit 2026-05-17 / OI-15. Background: `cron.job_run_details.status='succeeded'`
 * only confirms the pg_cron-side `net.http_post()` dispatch succeeded; it does NOT
 * reflect the Edge Function's actual HTTP response. During the Vault drift incident
 * (2026-05-11..16, CLAUDE.md §19 entry "pr-detection cron loops 401 every 15 min"),
 * pg_cron reported 1066 "succeeded" runs across a week while every single call returned
 * 401 server-side and zero work happened.
 *
 * Each cron Edge Function imports this helper and:
 *   1. Calls `logCronStart(name)` at the top of its `serve` handler → returns a row id.
 *   2. Calls `logCronEnd(id, status, httpStatus?, errorSummary?)` before returning.
 *
 * The row lands in `public.cron_call_log` (migration 068). Retention: 7 days via
 * `public.cleanup_cron_call_log()` (must be wired by founder via pg_cron registration
 * — currently not scheduled; see open_issues.md OI-15 follow-up).
 *
 * Failures inside the telemetry call itself are SWALLOWED (try/catch + debug log).
 * Cron functions MUST NOT 500 because telemetry is broken.
 */

import { createClient, SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2.39.3";

const SUPABASE_URL = Deno.env.get("SUPABASE_URL") ?? "";
const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? "";

type CronLogStatus = "success" | "failed";

let _adminClient: SupabaseClient | null = null;

function adminClient() {
  if (_adminClient) return _adminClient;
  if (!SUPABASE_URL || !SUPABASE_SERVICE_ROLE_KEY) {
    // Edge runtime quirk — should never happen in prod, but don't crash if it does.
    return null;
  }
  _adminClient = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);
  return _adminClient;
}

/**
 * Insert a `started` row. Returns the row id so the caller can update on exit.
 *
 * Returns `null` if telemetry insert fails — callers should pass that null straight
 * back into `logCronEnd` (which is a no-op on null id). The function itself never
 * throws.
 */
export async function logCronStart(functionName: string): Promise<number | null> {
  try {
    const supabase = adminClient();
    if (!supabase) return null;
    const { data, error } = await supabase
      .from("cron_call_log")
      .insert({ function_name: functionName, status: "started" })
      .select("id")
      .single();
    if (error || !data) {
      console.warn(`[cron_telemetry] start insert failed for ${functionName}`, error);
      return null;
    }
    return (data as { id: number }).id;
  } catch (e) {
    console.warn(`[cron_telemetry] start exception for ${functionName}`, e);
    return null;
  }
}

/**
 * Update the row created by `logCronStart` with terminal status.
 *
 * Passes-through silently when `id` is null (i.e. start insert failed).
 */
export async function logCronEnd(
  id: number | null,
  status: CronLogStatus,
  opts?: { httpStatus?: number; requestId?: string; errorSummary?: string },
): Promise<void> {
  if (id == null) return;
  try {
    const supabase = adminClient();
    if (!supabase) return;
    const patch: Record<string, unknown> = { status };
    if (opts?.httpStatus !== undefined) patch.http_status = opts.httpStatus;
    if (opts?.requestId) patch.request_id = opts.requestId;
    if (opts?.errorSummary) {
      // Cap error summary at 1000 chars to avoid bloat from giant stack traces.
      patch.error_summary = opts.errorSummary.slice(0, 1000);
    }
    const { error } = await supabase
      .from("cron_call_log")
      .update(patch)
      .eq("id", id);
    if (error) {
      console.warn(`[cron_telemetry] end update failed for id=${id}`, error);
    }
  } catch (e) {
    console.warn(`[cron_telemetry] end exception for id=${id}`, e);
  }
}

/**
 * paged_fetch — bounded reads for cron Edge Functions (OI-79).
 *
 * ## The bug this exists to prevent
 *
 * PostgREST caps every response at `db-max-rows` (1000 on this project) and
 * **supabase-js gives you no way to notice**. Measured live 2026-08-01 against
 * `dedsavbjuwgarrhphgnl`, `food_database` (1431 rows):
 *
 * | request                                   | status | Content-Range | rows |
 * |-------------------------------------------|--------|---------------|------|
 * | `?select=id` (what `.select()` sends)      | 200 OK | `0-999/*`     | 1000 |
 * | `Range: 0-1499`                            | 200 OK | `0-999/*`     | 1000 |
 * | `Range: 1000-1999`                         | 200 OK | `1000-1430/*` |  431 |
 * | `Prefer: count=exact`                      | 206    | `0-999/1431`  | 1000 |
 *
 * Three things follow, and each one is load-bearing:
 *
 * 1. **It is a 200, not a 206.** OI-79 was filed saying truncation shows up as
 *    `206 Partial Content`. That is only true when the caller asks for a count,
 *    and no cron function here does. In the shape our code actually sends, the
 *    response is a plain `200 OK` with a short body and `error === null`. There
 *    is no status, no error, and no total (`/*`) to compare against — a
 *    truncated read is *byte-for-byte indistinguishable* from a small one. The
 *    only signal is the row count, and it is AMBIGUOUS: a page shorter than
 *    `pageSize` means either end-of-data or a server cap below `pageSize`.
 *    That is why the loop terminates on an EMPTY page, never a short one.
 * 2. **`.range()` cannot raise the cap.** Asking for 0-1499 still yields 1000.
 *    So `pageSize` MUST be <= the cap; a larger value does not fetch more, it
 *    silently breaks the loop (you ask for 1500, get 1000, read that as a short
 *    page, and stop early — dropping every row after the first page).
 * 3. **Paging past the cap works.** Offset 1000-1999 returns the remainder.
 *    A `.range()` loop is therefore a real fix, not a workaround.
 *
 * ## Why `orderBy` is required and has no default
 *
 * Postgres guarantees no row order without an `ORDER BY`, and PostgREST adds
 * none. Two `.range()` calls against an unordered relation may return
 * overlapping or disjoint slices, so a paginated loop without a stable sort key
 * can **duplicate or skip rows** — silently, and only under load. Three loops in
 * this repo shipped that way (`morning-alert`, `weekly-recap-ready`,
 * `weekly-recalc`); `i-see-you-callout` got it right with
 * `.order("id", { ascending: true })`. Making `orderBy` a required parameter
 * with no default is how that mistake becomes unconstructible here.
 *
 * Pick a key that is **unique and immutable** — a primary key. A non-unique key
 * (`date`, `status`) does not fully order the rows, so ties can shuffle between
 * page requests and reintroduce the same skip/duplicate bug.
 *
 * ## RPCs
 *
 * `.order()` / `.range()` are accepted on `/rpc/` set-returning functions, so
 * both helpers work with `() => supabase.rpc(...)`. Whether `db-max-rows` also
 * caps RPC responses could not be settled from here: the only anon-executable
 * set-returning functions on this project are not `SECURITY DEFINER`, so RLS
 * returns 0 rows to `anon` and the probe is inconclusive. It does not change
 * anything — these helpers page unconditionally, which is correct either way
 * (if the cap does not apply, the loop simply ends on the first empty page).
 *
 * @see docs/audit/open_issues.md OI-79
 */

// deno-lint-ignore-file no-explicit-any

/**
 * PostgREST's server-side `db-max-rows` for this project, confirmed live
 * (table above). A response can never exceed this many rows regardless of the
 * requested `Range`.
 */
export const POSTGREST_MAX_ROWS = 1000;

/** Default page size. Sits at the cap: the largest value that is still safe. */
export const DEFAULT_PAGE_SIZE = 1000;

/**
 * Default `.in()` chunk size. Bounds the **request URL**, which is a different
 * constraint from `pageSize` (which bounds the *response*). A uuid costs ~37
 * bytes in `in.(...)`, so 100 ids is ~3.7KB and stays clear of the ~4-8KB URL
 * limits proxies impose. Matches the existing `BATCH_SIZE = 100` precedent in
 * `evaluate-rank-promotions`.
 */
export const DEFAULT_CHUNK_SIZE = 100;

/**
 * Runaway guard. At the default page size this permits 10M rows, far beyond any
 * legitimate cron scan — it exists to turn "PostgREST keeps returning full
 * pages forever" (an unstable sort key, a clock-skewed filter) into a loud
 * failure instead of an Edge Function that runs until the platform kills it.
 */
export const DEFAULT_MAX_PAGES = 10_000;

/** Minimal structural shape we need from a supabase-js query builder. */
interface RangeableBuilder {
  order(column: string, opts: { ascending: boolean }): RangeableBuilder;
  range(from: number, to: number): PromiseLike<{ data: unknown; error: unknown }>;
}

/** One ORDER BY term. */
export interface OrderKey {
  column: string;
  ascending?: boolean;
}

export interface PagedFetchOptions {
  /**
   * REQUIRED. Sort key — must be unique and immutable (a primary key). See the
   * header note on why this has no default.
   *
   * Pass an array to sort by several columns, e.g. to page a "most recent row
   * per user" read while preserving its ordering semantics:
   * `[{ column: "snapshot_date", ascending: false }, { column: "id" }]`.
   * The **last** term must be unique — the earlier ones can tie, and ties
   * without a unique tiebreaker are exactly the unstable-page bug.
   */
  orderBy: string | OrderKey[];
  /**
   * Sort direction for the single-column form. Ignored when `orderBy` is an
   * array (each term carries its own).
   */
  ascending?: boolean;
  /** Rows per request. MUST be <= {@link POSTGREST_MAX_ROWS}; see header note 2. */
  pageSize?: number;
  /** Runaway guard, see {@link DEFAULT_MAX_PAGES}. */
  maxPages?: number;
  /** Prefix for the saturation log line. Defaults to "paged_fetch". */
  label?: string;
}

/** Normalises the `orderBy` union into a non-empty list of ORDER BY terms. */
function orderKeys(opts: PagedFetchOptions): OrderKey[] {
  const bad = () => {
    throw new Error(
      "paged_fetch: `orderBy` is required and must be a non-empty column name " +
        "(or a non-empty array of them). A .range() loop without a stable sort " +
        "key can skip or duplicate rows (OI-79).",
    );
  };

  if (typeof opts.orderBy === "string") {
    if (!opts.orderBy.trim()) bad();
    return [{ column: opts.orderBy, ascending: opts.ascending ?? true }];
  }
  if (!Array.isArray(opts.orderBy) || opts.orderBy.length === 0) bad();
  const keys = (opts.orderBy as OrderKey[]).map((k) => {
    if (!k || typeof k.column !== "string" || !k.column.trim()) bad();
    return { column: k.column, ascending: k.ascending ?? true };
  });
  return keys;
}

function validate(opts: PagedFetchOptions): { pageSize: number; maxPages: number } {
  orderKeys(opts); // throws when the sort key is missing or malformed
  const pageSize = opts.pageSize ?? DEFAULT_PAGE_SIZE;
  if (!Number.isInteger(pageSize) || pageSize < 1) {
    throw new Error(`paged_fetch: pageSize must be a positive integer, got ${pageSize}`);
  }
  if (pageSize > POSTGREST_MAX_ROWS) {
    throw new Error(
      `paged_fetch: pageSize ${pageSize} exceeds PostgREST's db-max-rows ` +
        `(${POSTGREST_MAX_ROWS}). A larger page cannot fetch more rows — the server ` +
        `silently clamps it — so every page costs a full round-trip for at most ` +
        `${POSTGREST_MAX_ROWS} rows while the arithmetic implies more. The loop itself is ` +
        `SAFE at any cap (it advances by rows received and stops only on an empty page), ` +
        `so this is a wrong-configuration guard, not a correctness one. ` +
        `Use a pageSize <= ${POSTGREST_MAX_ROWS} (OI-79).`,
    );
  }
  const maxPages = opts.maxPages ?? DEFAULT_MAX_PAGES;
  if (!Number.isInteger(maxPages) || maxPages < 1) {
    throw new Error(`paged_fetch: maxPages must be a positive integer, got ${maxPages}`);
  }
  return { pageSize, maxPages };
}

/**
 * Reads **every** row matching a query, paging until an EMPTY page arrives.
 *
 * `makeQuery` must return a fresh builder each call — supabase-js builders are
 * single-use thenables, so reusing one across pages does not work. Apply your
 * filters there and let this apply `.order()` and `.range()`:
 *
 * ```ts
 * const rows = await fetchAllPages<{ user_id: string }>(
 *   () => supabase.from("coach_memory").select("user_id").gte("dropout_risk_score", 0.5),
 *   { orderBy: "user_id", label: "re-engagement path A" },
 * );
 * ```
 *
 * Throws on the first page error rather than returning partial rows. That is
 * deliberate: silently proceeding with an incomplete candidate set is the exact
 * failure this module exists to prevent, and a cron tick that cannot read its
 * inputs should fail loudly and retry on the next tick.
 */
export async function fetchAllPages<T>(
  makeQuery: () => unknown,
  opts: PagedFetchOptions,
): Promise<T[]> {
  const { pageSize, maxPages } = validate(opts);
  const keys = orderKeys(opts);
  const label = opts.label ?? "paged_fetch";
  const keyDesc = keys.map((k) => `${k.column}${k.ascending ? "" : " desc"}`).join(", ");

  const all: T[] = [];

  for (let page = 0; ; page++) {
    if (page >= maxPages) {
      throw new Error(
        `paged_fetch[${label}]: exceeded maxPages=${maxPages} (${all.length} rows read). ` +
          `Every page came back full — check that orderBy='${keyDesc}' ends in a unique, ` +
          `immutable column; an unstable sort key can loop forever.`,
      );
    }

    // Offset by rows ACTUALLY received, never by `page * pageSize`. The two
    // agree only while the server serves full pages, and `db-max-rows` is a
    // dashboard setting (Settings -> API -> Max rows), not a platform
    // invariant. Lower it to 500 and the old arithmetic broke completely:
    // page 0 asked 0-999, got 500, and `500 < pageSize` read as end-of-data —
    // so every one of the reads this module was written to fix would silently
    // return 500 rows with error === null. Advancing by `all.length` makes the
    // loop correct for ANY server cap without having to know what it is.
    const from = all.length;
    const to = from + pageSize - 1;

    let q = makeQuery() as RangeableBuilder;
    for (const k of keys) q = q.order(k.column, { ascending: k.ascending ?? true });
    const builder = q.range(from, to);

    const { data, error } = await builder;
    if (error) {
      throw new Error(
        `paged_fetch[${label}]: page ${page} (rows ${from}-${to}) failed: ` +
          `${(error as { message?: string } | null)?.message ?? String(error)}`,
      );
    }

    const rows = (data ?? []) as T[];
    all.push(...rows);

    // Only an EMPTY page proves end-of-data. A SHORT page does not: it is
    // equally the signature of a server cap below `pageSize` (see the offset
    // note above), and treating it as "done" is exactly the silent truncation
    // this module exists to prevent.
    //
    // COST, stated honestly. For `fetchAllPages` this is one extra round-trip
    // per read. For `fetchAllByIds` it is one extra per CHUNK, and with
    // DEFAULT_CHUNK_SIZE = 100 a chunk essentially never fills a 1000-row
    // page — so the confirming request lands on ~every chunk, not on a rare
    // boundary. 12 chunked call sites; at ~10k PRO users protein-gap-alert
    // goes from roughly 300 to 600 sequential round-trips per tick. Accepted
    // deliberately: these are daily cron jobs where wall-clock is cheap, and
    // the alternative is a read that silently returns half its rows with
    // error === null. If round-trips ever become the constraint, learn the
    // server's real page size once per process instead. (Corrected after
    // round-2 review — the earlier note claimed "the same one the
    // exact-multiple case already paid", true of fetchAllPages and NOT of the
    // chunked path that dominates.)
    if (rows.length === 0) break;
  }

  return all;
}

/**
 * Reads every row for a set of ids, chunking the `.in()` list **and** paging
 * within each chunk.
 *
 * Chunking alone is not enough, and that distinction is the whole point of this
 * function. `evaluate-rank-promotions` already had a `fetchInChunks` helper that
 * split `userIds` into batches of 100 — but a chunk bounds the *request*, not
 * the *response*. One 100-id chunk against a table holding N rows per user
 * returns 100xN rows, so it truncates at 10 rows/user no matter how small the
 * chunk is. This pages inside each chunk, which bounds both.
 *
 * ```ts
 * const logs = await fetchAllByIds<{ user_id: string }>(
 *   (chunk) => supabase.from("nutrition_logs")
 *                      .select("user_id, total_protein")
 *                      .eq("date", todayIST)
 *                      .in("user_id", chunk),
 *   proUserIds,
 *   { orderBy: "id", label: "protein-gap-alert nutrition" },
 * );
 * ```
 */
export async function fetchAllByIds<T>(
  makeQuery: (idChunk: string[]) => unknown,
  ids: string[],
  opts: PagedFetchOptions & { chunkSize?: number },
): Promise<T[]> {
  validate(opts);

  const chunkSize = opts.chunkSize ?? DEFAULT_CHUNK_SIZE;
  if (!Number.isInteger(chunkSize) || chunkSize < 1) {
    throw new Error(`paged_fetch: chunkSize must be a positive integer, got ${chunkSize}`);
  }

  if (ids.length === 0) return [];

  const all: T[] = [];
  for (let i = 0; i < ids.length; i += chunkSize) {
    const chunk = ids.slice(i, i + chunkSize);
    const rows = await fetchAllPages<T>(() => makeQuery(chunk), {
      ...opts,
      label: `${opts.label ?? "paged_fetch"} chunk@${i}`,
    });
    all.push(...rows);
  }
  return all;
}
